#define LRU_CACHE_HPP

#include <cstddef>
#include <list>
#include <mutex>
#include <optional>
#include <unordered_map>

template <typename K, typename V>
class LRUCache {
public:
    explicit LRUCache(std::size_t capacity) : capacity_(capacity) {}

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = map_.find(key);
        if (it == map_.end()) {
            return std::nullopt;
        }
        // A hit counts as a use: move to front (most recently used).
        list_.splice(list_.begin(), list_, it->second);
        return it->second->second;
    }

    void put(const K& key, const V& value) {
        if (capacity_ == 0) return;  // nothing can be stored
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = map_.find(key);
        if (it != map_.end()) {
            // Update existing key; counts as a use.
            it->second->second = value;
            list_.splice(list_.begin(), list_, it->second);
            return;
        }

        if (map_.size() >= capacity_) {
            // Evict the least recently used (back of the list).
            auto& lru = list_.back();
            map_.erase(lru.first);
            list_.pop_back();
        }

        list_.push_front({key, value});
        map_.insert({key, list_.begin()});
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return map_.size();
    }

private:
    std::size_t capacity_;
    std::mutex mutex_;
    std::list<std::pair<K, V>> order_;  // front = most recent, back = least recent
    std::unordered_map<K, std::list<std::pair<K, V>>::iterator> map_;
};

#endif  // LRU_CACHE_HPP
```

