class Matrix {
public:
    Matrix(int rows, int cols)
        : rows_(rows), cols_(cols), data_(new double[static_cast<std::size_t>(rows) * cols]{}) {}

    ~Matrix() { delete[] data_; }

    Matrix(const Matrix& other)
        : rows_(other.rows_), cols_(other.cols_), data_(new double[rows_ * cols_]) {
        for (std::size_t i = 0; i < static_cast<std::size_t>(rows_) * cols_; ++i)
            data_[i] = other.data_[i];
    }

    Matrix(Matrix&& other) noexcept
        : rows_(other.rows_), cols_(other.cols_), data_(other.data_) {
        other.rows_ = 0;
        other.cols_ = 0;
        other.data_ = nullptr;
    }

    Matrix& operator=(const Matrix& other) {
        if (this != &other) {
            double* nd = new double[other.rows_ * other.cols_];
            for (std::size_t i = 0; i < static_cast<std::size_t>(other.rows_) * other.cols_; ++i)
                nd[i] = other.data_[i];
            delete[] data_;
            data_ = nd;
            rows_ = other.rows_;
            cols_ = other.cols_;
        }
        return *this;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            other.rows_ = 0;
            other.cols_ = 0;
            other.data_ = nullptr;
        }
        return *this;
    }

    double& at(int r, int c) {
        bounds_check(r, c);
        return data_[static_cast<std::size_t>(r) * cols_ + c];
    }

    double at(int r, int c) const {
        bounds_check(r, c);
        return data_[static_cast<std::size_t>(r) * cols_ + c];
    }

    int rows() const { return rows_; }
    int cols() const { return cols_; }

    Matrix operator+(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_)
            throw std::invalid_argument("Matrix operator+: size mismatch");
        Matrix result(rows_, cols_);
        for (std::size_t i = 0; i < static_cast<std::size_t>(rows_) * cols_; ++i)
            result.data_[i] = data_[i] + o.data_[i];
        return result;
    }

    Matrix operator*(const Matrix& o) const {
        if (cols_ != o.rows_)
            throw std::invalid_argument("Matrix operator*: size mismatch");
        Matrix result(rows_, o.cols_);
        for (int r = 0; r < rows_; ++r)
            for (int c = 0; c < o.cols_; ++c) {
                double sum = 0.0;
                for (int k = 0; k < cols_; ++k)
                    sum += at(r, k) * o.at(k, c);
                result.at(r, c) = sum;
            }
        return result;
    }

    bool operator==(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_)
            return false;
        for (std::size_t i = 0; i < static_cast<std::size_t>(rows_) * cols_; ++i)
            if (data_[i] != o.data_[i])
                return false;
        return true;
    }

private:
    void bounds_check(int r, int c) const {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_)
            throw std::out_of_range("Matrix::at: index out of range");
    }

    int rows_;
    int cols_;
    double* data_;
};
