import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;

public class Library {

    private static final class Loan {
        private final String member;
        private final LocalDate date;

        Loan(String member, LocalDate date) {
            this.member = member;
            this.date = date;
        }
    }

    private final Map<String, String> books = new HashMap<>();
    private final Map<String, Loan> loans = new HashMap<>();

    public void addBook(String isbn, String title) {
        if (isbn == null) {
            throw new IllegalArgumentException("isbn must not be null");
        }
        if (books.containsKey(isbn)) {
            throw new IllegalArgumentException("Book already exists: " + isbn);
        }
        books.put(isbn, title);
    }

    public void borrow(String isbn, String member, LocalDate date) {
        if (!books.containsKey(isbn)) {
            throw new NoSuchElementException("Unknown isbn: " + isbn);
        }
        if (loans.containsKey(isbn)) {
            throw new IllegalStateException("Book already borrowed: " + isbn);
        }
        loans.put(isbn, new Loan(member, date));
    }

    public void giveBack(String isbn) {
        if (!books.containsKey(isbn)) {
            throw new NoSuchElementException("Unknown isbn: " + isbn);
        }
        if (!loans.containsKey(isbn)) {
            throw new IllegalStateException("Book not borrowed: " + isbn);
        }
        loans.remove(isbn);
    }

    public List<String> overdue(LocalDate today, int days) {
        List<String> result = new ArrayList<>();
        for (Map.Entry<String, Loan> entry : loans.entrySet()) {
            long borrowedDays = ChronoUnit.DAYS.between(entry.getValue().date, today);
            if (borrowedDays > days) {
                result.add(books.get(entry.getKey()));
            }
        }
        result.sort(String::compareTo);
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> result = new HashMap<>();
        for (Loan loan : loans.values()) {
            result.merge(loan.member, 1, Integer::sum);
        }
        return result;
    }
}
